    "seoTitle": "Agency Profit Margin: Payroll and Capacity",
    "description": "Calculate agency profit margin with committed payroll, client costs and owner pay. Test a lost retainer and check whether the monthly client target fits.",
    "metaDescription": "Calculate agency profit margin with committed payroll, client costs and owner pay. Test a lost retainer and check whether the monthly client target fits.",
    "image": "/images/blog/day3-agency-margin.webp",
